import{_ as t,o as i,c as n,a2 as s}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Embeddings","description":"Embeddings reference documentation","frontmatter":{"title":"Embeddings","description":"Embeddings reference documentation"},"headers":[],"relativePath":"knowledge/embeddings.md","filePath":"knowledge/embeddings.md","lastUpdated":1784485118000}'),a={name:"knowledge/embeddings.md"};function r(o,e,d,l,c,g){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="embeddings" tabindex="-1">Embeddings <a class="header-anchor" href="#embeddings" aria-label="Permalink to &quot;Embeddings&quot;">​</a></h1><h1 id="text-embeddings-—-knowledge-base" tabindex="-1">Text Embeddings — Knowledge Base <a class="header-anchor" href="#text-embeddings-—-knowledge-base" aria-label="Permalink to &quot;Text Embeddings — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Text embeddings convert text into dense numerical vectors that capture semantic meaning. Similar texts produce similar vectors, enabling semantic search, clustering, classification, and RAG. This knowledge base covers embedding models, similarity metrics, and production integration patterns.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="what-are-embeddings" tabindex="-1">What Are Embeddings? <a class="header-anchor" href="#what-are-embeddings" aria-label="Permalink to &quot;What Are Embeddings?&quot;">​</a></h3><p>Embeddings represent text as fixed-length vectors in high-dimensional space. A sentence like &quot;How do I reset my password?&quot; is converted to a vector like <code>[0.023, -0.156, 0.089, ...]</code> (typically 384-3072 dimensions).</p><p><strong>Key property:</strong> Semantically similar texts have nearby vectors in the embedding space.</p><h3 id="embedding-models" tabindex="-1">Embedding Models <a class="header-anchor" href="#embedding-models" aria-label="Permalink to &quot;Embedding Models&quot;">​</a></h3><p><strong>OpenAI models:</strong></p><ul><li><code>text-embedding-3-small</code> — 1536 dimensions, cost-effective, good general performance</li><li><code>text-embedding-3-large</code> — 3072 dimensions, highest accuracy, higher cost</li></ul><p><strong>Open-source models:</strong></p><ul><li><code>all-MiniLM-L6-v2</code> — 384 dimensions, fast, good for English</li><li><code>multilingual-e5-large</code> — 1024 dimensions, supports 100+ languages including Arabic</li><li><code>bge-large-en-v1.5</code> — 1024 dimensions, strong retrieval performance</li></ul><p><strong>Model selection factors:</strong> Dimensionality, speed, accuracy, language support, hosting requirements, cost.</p><h3 id="similarity-metrics" tabindex="-1">Similarity Metrics <a class="header-anchor" href="#similarity-metrics" aria-label="Permalink to &quot;Similarity Metrics&quot;">​</a></h3><p><strong>Cosine similarity</strong> — Measures angle between vectors (range: -1 to 1). Most common; independent of magnitude.</p><p><strong>Dot product</strong> — Measures combined magnitude and direction. Use when vector magnitude is meaningful.</p><p><strong>Euclidean distance</strong> — Straight-line distance between vectors. Lower = more similar.</p><p><strong>When to use which:</strong></p><ul><li>Normalized vectors → cosine similarity (default choice)</li><li>Unnormalized vectors with magnitude meaning → dot product</li><li>Geometric analysis → Euclidean distance</li></ul><h3 id="dimensionality" tabindex="-1">Dimensionality <a class="header-anchor" href="#dimensionality" aria-label="Permalink to &quot;Dimensionality&quot;">​</a></h3><p><strong>Higher dimensions</strong> — More expressive, capture finer distinctions, but slower and more expensive to store/search.</p><p><strong>Lower dimensions</strong> — Faster and cheaper, but may lose nuanced meaning. Sufficient for most use cases.</p><p><strong>Dimensionality reduction:</strong> Techniques like PCA or Matryoshka Representation Learning (MRL) allow using subsets of dimensions.</p><h3 id="batch-processing" tabindex="-1">Batch Processing <a class="header-anchor" href="#batch-processing" aria-label="Permalink to &quot;Batch Processing&quot;">​</a></h3><p>Embedding multiple texts in a single API call is more efficient than individual calls:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Single:  100 texts × 100ms = 10 seconds</span></span>
<span class="line"><span>Batch:   100 texts in 1 call × 200ms = 0.2 seconds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Batch limits:</strong> OpenAI allows 2048 texts per request; most models have similar batch limits.</p><h3 id="cost-vs-quality" tabindex="-1">Cost vs Quality <a class="header-anchor" href="#cost-vs-quality" aria-label="Permalink to &quot;Cost vs Quality&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Dimensions</th><th>Cost per 1M tokens</th><th>Best for</th></tr></thead><tbody><tr><td>text-embedding-3-small</td><td>1536</td><td>$0.02</td><td>General use, cost-sensitive</td></tr><tr><td>text-embedding-3-large</td><td>3072</td><td>$0.13</td><td>Maximum accuracy, complex queries</td></tr><tr><td>all-MiniLM-L6-v2</td><td>384</td><td>Free (local)</td><td>Self-hosted, English-only</td></tr><tr><td>multilingual-e5-large</td><td>1024</td><td>Free (local)</td><td>Multilingual, Arabic support</td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Choose multilingual embeddings for bilingual apps</strong> — Use <code>multilingual-e5-large</code> or OpenAI&#39;s models for Arabic/English content; test embedding quality for both languages</li><li><strong>Preprocess text before embedding</strong> — Strip HTML, normalize whitespace, remove special characters; clean input produces better embeddings</li><li><strong>Use batch embedding for efficiency</strong> — Embed multiple texts per API call; batch processing is 10-50x faster than individual calls</li><li><strong>Normalize vectors for cosine similarity</strong> — If using cosine similarity, normalize vectors to unit length; most embedding APIs do this automatically</li><li><strong>Store embeddings alongside metadata</strong> — Each embedding should be associated with source ID, chunk text, and metadata for retrieval</li><li><strong>Test embedding quality empirically</strong> — Don&#39;t assume one model is best for your domain; create a test set and measure retrieval accuracy</li><li><strong>Plan for dimensionality in storage</strong> — Higher dimensions require more storage and slower search; choose dimensions that match your accuracy requirements</li><li><strong>Implement embedding caching</strong> — Cache embeddings for unchanged text; re-embedding identical text wastes API calls</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Embedding raw HTML or markup</strong> — Strip formatting before embedding; HTML tags add noise that degrades semantic quality</li><li><strong>Embedding entire documents as one vector</strong> — Large documents lose nuance in a single embedding; chunk first, then embed each chunk</li><li><strong>Using the wrong similarity metric</strong> — Mixing dot product with normalized vectors or vice versa produces incorrect rankings</li><li><strong>Ignoring embedding drift</strong> — Different versions of embedding models produce incompatible vectors; version your embeddings and migrate when upgrading</li><li><strong>Embedding without dimension planning</strong> — Storing 3072-dimensional vectors when 384 suffices wastes 8x storage and slows search</li><li><strong>Not handling multilingual text</strong> — English-only models produce poor embeddings for Arabic; use multilingual models</li><li><strong>Embedding in the wrong order</strong> — Text preprocessing (normalization, cleaning) must happen before embedding, not after</li><li><strong>Treating embeddings as encryption</strong> — Embeddings are not secure; text can be reconstructed from embeddings with sufficient effort</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not chunking before embedding</strong> — Large text blocks produce vague embeddings; chunk into 256-1024 token segments before embedding</li><li><strong>Inconsistent preprocessing</strong> — Different cleaning for query vs document embeddings breaks similarity; use identical preprocessing</li><li><strong>Ignoring embedding latency</strong> — Embedding APIs add latency to queries; cache frequently-embedded text and use batch processing</li><li><strong>Mixing embedding model versions</strong> — v1 and v2 embeddings are incompatible; don&#39;t mix versions in the same vector store</li><li><strong>Forgetting token limits</strong> — Embedding models have token limits (8192 for OpenAI); truncate or chunk long text before embedding</li><li><strong>Not testing with actual queries</strong> — Embedding quality depends on query-document matching; test with real user queries</li><li><strong>Over-indexing on benchmark scores</strong> — Model benchmarks may not reflect your domain performance; test with your specific data</li><li><strong>Neglecting Arabic text tokenization</strong> — Arabic text may tokenize differently; ensure embedding model handles Arabic morphology correctly</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Recommendation</th></tr></thead><tbody><tr><td>Cost-sensitive, English only</td><td>all-MiniLM-L6-v2 (self-hosted)</td></tr><tr><td>Arabic + English</td><td>multilingual-e5-large or text-embedding-3-small</td></tr><tr><td>Maximum accuracy</td><td>text-embedding-3-large with reranking</td></tr><tr><td>Privacy-sensitive data</td><td>Self-hosted model (no API calls)</td></tr><tr><td>Real-time search</td><td>Smaller dimensions (384-768) with HNSW index</td></tr><tr><td>Batch indexing</td><td>text-embedding-3-small with batch API</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>OpenAI Embeddings Guide: <a href="https://platform.openai.com/docs/guides/embeddings" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/embeddings</a></li><li>Sentence Transformers: <a href="https://www.sbert.net/" target="_blank" rel="noreferrer">https://www.sbert.net/</a></li><li>MTEB Leaderboard: <a href="https://huggingface.co/spaces/mteb/leaderboard" target="_blank" rel="noreferrer">https://huggingface.co/spaces/mteb/leaderboard</a></li><li>Hugging Face Embedding Models: <a href="https://huggingface.co/models?pipeline_tag=sentence-similarity" target="_blank" rel="noreferrer">https://huggingface.co/models?pipeline_tag=sentence-similarity</a></li><li>Supabase pgvector: <a href="https://supabase.com/docs/guides/database/extensions/pgvector" target="_blank" rel="noreferrer">https://supabase.com/docs/guides/database/extensions/pgvector</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Supabase storage:</strong> Store embeddings in a Supabase table with pgvector extension; create vector index for fast similarity search</li><li><strong>OpenAI embedding API:</strong> Simple POST request; use <code>input</code> parameter with string or array; returns embedding vectors</li><li><strong>Testing quality:</strong> Create 20-30 query-document pairs from your domain; measure recall@5 to evaluate embedding quality</li><li><strong>Arabic embeddings:</strong> Test with Arabic queries against Arabic documents; measure quality separately from English</li><li><strong>Cost tracking:</strong> Embedding costs are typically low compared to LLM costs; budget $1-10/month for most applications</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,44)])])}const u=t(a,[["render",r]]);export{h as __pageData,u as default};
